-- 0049_warming_instructions_affiliate.sql
--
-- Rewrites crm_status_rules.warming_instructions for the affiliate_marketing
-- agent, per the objection-handling workshop (all 29 active statuses).
-- These are the per-status DIRECTIVES injected into the agent's system prompt
-- ("## How to handle this lead") after a warmed lead replies.
--
-- Scope: affiliate_marketing ONLY. Guard-safe by construction (no prices,
-- amounts, discounts, income promises, or invented facts; institution names and
-- approved links are allowed). Pure content — does not enable warming or wire
-- any lead flow. Idempotent.
--
-- Disabled statuses (3, 5, 16, 19) are intentionally NOT updated here — see 0048.

update public.crm_status_rules r
set warming_instructions = v.txt
from public.agents a,
     (values
        (2,  $w$פעם ראשונה שלא ענה בטלפון — כנראה פשוט לא היה זמין, לא התנגדות. אחרי שהוא עונה לפתיח, הזכר בעדינות ובטון חברי שניסינו להשיג אותו ("ניסינו לתפוס אותך ולא הצלחנו"), בלי תחושת מרדף. משם שיח קליל והובלה לזום. טפל בהתנגדות רק אם הליד עצמו מעלה אותה.$w$),
        (4,  $w$אי-מענה שיטתי, אבל הפתיח כבר פתח בשאלה על המוטיבציה (כסף/חופש/סקרנות). אחרי שהוא עונה — התחבר ישירות לתשובה שלו, חמם בעדינות סביב מה שמניע אותו, והובל לזום. אנושי וקליל, בלי חקירה.$w$),
        (6,  $w$סבב שלם של אי-מענה → בוודאות יש היסוס/התנגדות. אחרי הפתיח "מה קורה?", לך חד וכן (מוכן לאבד חלק): הכר בכך שלא הצלחתם לדבר, ושאל שאלת-אמונה שמזיזה — "האם אתה מאמין שהמציאות שלנו משתנה בגלל הפעולות שלנו או רק מזל?". שאלה כזו מעוררת מחשבה ומושכת לשיח, וממנה הובל לבדיקת התאמה וזום.$w$),
        (7,  $w$הליד היה בשיחה עם מישהו אחר ולכן לא ענה — לא נמנע, פשוט לא היה פנוי. מגע קל: אחרי הפתיח, שיח קליל והובלה לזום, בלי להניח התנגדות.$w$),
        (14, $w$הליד העלה מול הנציג את נושא המחיר. אסור לנקוב במחיר/סכום/הנחה/תשלומים (ההודעה תיחסם). הסט מ"כמה זה עולה" ל"מה זה נותן". עוגן: יש מוסדות לימוד (למשל הבינתחומי בהרצליה מול אוניברסיטה ציבורית) שעולים הרבה יותר ואנשים בוחרים בהם ביודעין — בזכות הערך, הקשרים והדלתות שנפתחות, לא המחיר. אל תתנצל על העלות. שדר בעדינות שהכסף לא צריך לעצור אותו, ושהיועץ הוא זה שבודק מה מתאים לו אישית. הובל לזום.$w$),
        (15, $w$רצף: (1) קודם הבן מה חשוב לו. (2) לפי זה הדגש את הייחוד שלנו שעוזר במה שחיפש. (3) ורק אז שאל אם ההצעה שקיבל באמת כוללת את זה. "עוד מברר": אל תשחרר מהר — תן לו קריטריונים ברורים לבדוק בכל תוכנית, שמנוסחים כך שיצביעו על החוזקות שלנו (הכוונה, לא מכירה). אל תשמיץ מתחרים — חשוף פערים דרך שאלות. הובל לזום.$w$),
        (18, $w$הליד לא מאמין שהתוכנית עובדת, וחושב שאנחנו שקרנים כמו עוד מנטורים ברשת. אל תתגונן. פרק בשלושה: (1) ריפריים מיומנות — עורך דין מבריק ≠ בהכרח כסף; שיווק זה שונה: המקצוע של איך מביאים לקוחות ומובילים אותם לרכישה, המנוע של כל הכסף בעולם. מי שנעשה טוב בזה הופך למישהו שכל עסק צריך — כי הוא יודע להכניס לעסק לקוחות וכסף. עם זה אי אפשר להתווכח. (2) הוכחה מהמקור — רק אחרי חימום אמיתי בשיחה, שלח את הלינק המאושר לעדויות (המקור אומר את המספרים, לא אתה). (3) סיפור האחים סיטון (מה-brain) להזדהות. אל תמציא אחוזי הצלחה ואל תבטיח הכנסה.$w$),
        (20, $w$חוסר כימיה עם הנציג/הפרזנטור הקודם. אתה קול חדש — הזדמנות להתחלה נקייה. אל תתייחס לזה ישירות. עבוד חכם — גלה איזו כימיה כן תתפוס אותו ובנה אותה תוך כדי השיחה. הובל לזום עם יועץ אחר.$w$),
        (21, $w$לא עונה לטלפון כי יודע שזה נציג מכירות — בורח מהמוכר, לא מהמוצר. וואטסאפ = הערוץ הלא-לוחץ שלו. היה קליל, אנושי, אפס אווירת-מכירה (התנהגות, לא הצהרה), אולי הומר. שאלה קלה → זום ממוסגר כשיחה רגועה. הוא כבר דחה נציג, אז זום שנקבע סתם = הברזה. בנה buy-in ומחויבות אמיתיים לפני הקביעה.$w$),
        (22, $w$מעוניין אמיתי אבל לא בעיתוי הנוכחי. פתח בלי להזכיר את הדחייה, בדוק אם הנסיבות השתנו — ואם כן, הובל לזום. אם עדיין לא בשל — חמם באיכות ובעדינות, בלי לחץ, ושמור על הקשר חם עד שיבשיל.$w$),
        (23, $w$אף אחד לא נרשם לתוכנית הכנסה+חופש סתם → משהו מסתתר, חשוף אותו. הבא אותו לזום במקסימום מחויבות — חד על המחויבות לפני הקביעה, מוכן לאבד אותו. הגד את הרף במפורש: סלקטיביות משדרת יוקרה ורצינות — אבל אנושי ובגובה עיניים שלא יעורר אנטגוניזם. אם לא מגיע למחויבות — עדיף שלא יבוא.$w$),
        (24, $w$אין מידע על ההתנגדות. אל תנחש — פתח שיחה קלילה, גלה תוך כדי תנועה מה עומד מאחורי החשש, ורק אז טפל והובל לזום.$w$),
        (26, $w$ליד חם שרצה להיכנס וניסה לממן — ולא הסתדר. הוא כבר מאמין בערך; אל תשכנע בערך. אל תעלה כסף/מימון ביוזמתך ואל תרמז שאתה יודע. הובל שיחת מיינדסט: המציאות משתנה רק כשעושים צעד. עורר חשיבה איך להתחיל לייצר קצת בצד כמנוע ליציאה מהמצב — "אם היית מתחיל להכניס אפילו קצת מהצד, מה זה היה משנה לך?". אם הוא מעלה כסף — הכר בתסכול בכנות, בלי לחץ, ואז: "הכסף לא חייב להיות הקיר האחרון — בשביל זה יש שיחה עם היועץ שבודק מה אפשרי במצב שלך". אל תבטיח הכנסה/סכומים.$w$),
        (47, $w$אין מידע על ההתנגדות. אל תנחש — פתח שיחה קלילה, גלה תוך כדי תנועה מה עומד מאחורי החשש, ורק אז טפל והובל לזום.$w$),
        (50, $w$ליד חשדן/סגור. היה סופר-אנושי — התחל ללכת מסביב בלי פרטים, הקלל את האווירה עם טיפה הומור, ואז לאט-לאט אחרי שהוא נפתח — העמק שאלות בעדינות ולפי התגובות שלו. אף פעם אל תכריז על הטכניקה ("אני לא פה לחקור אותך") — זה רובוטי וסוגר אותו; פשוט התנהג בחום ובלי לחץ. בנה מיקרו-אמון → זום.$w$),
        (51, $w$הליד הגיע בהנחה שהכל חינם ונרתע מהעלות. אל תנקוב במחיר. חמם מחדש את המטרה שלו, ובנה הסכמה עקרונית: "כל דבר ששינה למישהו את החיים דרש ממנו משהו — מאמץ, זמן או כסף. השאלה היחידה היא אם המטרה שווה לך את זה." אחרי שהוא מסכים לעיקרון, העלות מרגישה לגיטימית — הובל לזום עם היועץ לפרטים המלאים. אל תבטיח הכנסה.$w$),
        (52, $w$הרים חומות, כרגע ידחה כל דבר. (1) אל תמכור — הצטרף לצד שלו: הבן מה הרים לו חומות, הגע להסכמות ("אני איתך"). (2) רק אז נתח את "המציאות" כגורם שלישי (לא עליו), כאילו אתה עוזר לו לבחון איך לשנות אותה. (3) גרום לו להרגיש חכם ומוערך דרך האופן שאתה מדבר איתו — אל תגיד לו "אתה גאון" (זה TELL); על המציאות מותר לומר במפורש שהיא דפוקה. קריטי: לא "ננצח יחד" — תן לו תחושה שהוא ינצח את המציאות בעצמו. לאט עד להבנות → זום.$w$),
        (54, $w$הליד אמר שאין לו כסף, וייתכן שבאמת אין. טפל כמו 26: בלי לחץ, בלי שכנוע-ערך. הובל מיינדסט — צעד כזה הוא בדיוק מה שיכול להתחיל לשנות את המצב. אם הוא מעלה כסף — הכר בכנות, והבהר שהכסף לא חייב להיות הקיר האחרון ושהיועץ בודק מה אפשרי. אל תנקוב במחיר/הנחה/תשלומים ואל תבטיח הכנסה. הובל לזום.$w$),
        (55, $w$הליד כבר ניסה משהו דומה ונכווה. (1) חקור מה בדיוק לא עבד לו. (2) כנות רדיקלית: דבר ישיר וכן — זה דורש השקעה ומאמץ אמיתיים, ואתה לא מבטיח הרים וגבעות (בדיוק השקר שכווה אותו). הכנות בונה אמון ומחויבות אצל מי שנכווה. הקשב לפני שאתה מציע, אל תבטל את החוויה שלו, והצע שיחה עם יועץ שיתייחס לזה ישירות. הובל לזום.$w$),
        (56, $w$הליד לא בטוח שהוא מסוגל — חשש רגשי. אל תפגיז אותו בעובדות/לוגיקה. בנה לו ביטחון דרך רפלקציה: "יש משהו שהיה נראה לך בהתחלה בלתי-אפשרי ובסוף הצלחת בו? מה גרם לך להצליח שם?". עבוד עד שהוא בעצמו יאמר שהוא מסוגל, ורק אז הובל לזום. הקטן את תחושת המאמץ, חזק את הוודאות שהוא יכול.$w$),
        (58, $w$הליד לא בטוח בלגיטימיות המכללה. אל תתגונן — ברר מה מטריד אותו. הישען על מקורות אמיתיים: ספר בגאווה את סיפור המכללה (הוקמה 2022, מה-brain), והצע לו להכיר אותנו בעצמו דרך עמוד האודות (לינק מאושר): "קח דקה תכיר אותנו: [לינק]". שקיפות חזקה מכל טיעון. הובל לזום. אל תמציא נתונים.$w$),
        (59, $w$אל תתגונן ואל תכחיש. (1) קודם ברר במה בדיוק נתקל ורק אז הפרך ספציפית. (2) השוואה: לכל מוסד יש לא-מרוצים; השאלה אם הרוב מרוצים ("כולם באוניברסיטה מרוצים?"). (3) הסלמה: אוניברסיטאות לא מעזות לדבר על תוצאה בכלל — "אנחנו דווקא לא מתביישים להתעסק בשינוי אמיתי בחיים (משפחה, פיתוח, חופש), לא רק בתוכן יפה". (4) הרגעה: במקום לטעון סטטיסטיקה — שלח את לינק העדויות ("אל תסמוך עליי, תראה בעצמך"), ונציין שאנחנו 4+ שנים בשוק. אל תמסגר תוצאות כהבטחת הכנסה ואל תטען מספרים בעצמך.$w$),
        (60, $w$אל תסתור את "אין זמן" — קבל שזה אמיתי. דרך שאלה הובל אותו להבין בעצמו שזמן לא "מופיע" כשממשיכים אותו דבר — הוא מתפנה רק כשבונים משהו שמשנה את המצב. קריטי: שהוא יגיד את זה, לא אתה. "אם תמשיך בדיוק כמו עכשיו — הזמן הזה יופיע לך מאיפשהו? או שדווקא צריך לעשות משהו אחר כדי שיתפנה?". אחרי שהוא מסכים — הצע התקדמות לזום.$w$),
        (72, $w$הליד נרשם (משהו סיקרן אותו) אבל הוריד את המוכר מהר. אל תשתמש בוו גנרי. גלה מה סיקרן אותו מלכתחילה — "כשנרשמת משהו כן תפס אותך, מה זה היה?" — ולפי זה חבר צורך ורצון והצת מחדש את העניין. נצל שזה וואטסאפ (בלי לחץ של שיחת טלפון), היה אנושי וקליל, אולי טיפה הומר. הובל לזום רגוע.$w$),
        (73, $w$הליד נרשם (משהו סיקרן אותו) אבל ניתק בפתיח מהר. אל תשתמש בוו גנרי. גלה מה סיקרן אותו מלכתחילה — "כשנרשמת משהו כן תפס אותך, מה זה היה?" — ולפי זה חבר צורך ורצון והצת מחדש את העניין. נצל שזה וואטסאפ (בלי לחץ של שיחת טלפון), היה אנושי וקליל, אולי טיפה הומר. הובל לזום רגוע.$w$),
        (76, $w$בן/בת הזוג שימש להוריד את העסקה. הנח ש-100% זה באמת בן/בת הזוג — אל תחקור אם הוא מסתתר מאחורי זה. אמץ את זה בכבוד: הוא רוצה זוגיות טובה, והחלטה משמעותית כזו היא בצדק החלטה זוגית — זה נכון ובריא. אל תזכיר את הדחייה, ואל תערער על ההחלטה המשותפת. הצף בעדינות את מחיר ההישארות במצב בצורה שגורמת לו לרצות לפתוח מחדש את השיחה עם בן/בת הזוג. הצע זום משותף ששניהם נוכחים ומחליטים יחד — מנטרל את "צריך להתייעץ". חמש את הליד לנטרל את ההתנגדויות שלהם. אל תנקוב בסכומים.$w$),
        (77, $w$(1) גלה למה הוא כן מתחבר — במה הוא עוסק היום, אם אוהב, ומה המטרות שחשובות לו. (2) reframe: כולנו מקריבים בעבודה — אבל יש עבודה שמשרתת את המטרות שלך ויש שלא. "אם היו לך מיליארדים בבנק, היית עובד היום את מה שאתה עובד ובאותו היקף?". (3) חבר את מה שהוא אוהב → הראה איך העבודה הזו מגשימה את זה. פסילה כנה (סף גבוה מאוד): רק אם 100% ברור שממש לא בשבילו ושרק יאוכזב — שחרר בעדינות. ברירת המחדל להתמיד.$w$),
        (80, $w$הליד אמר "לא בשבילי". קודם גלה למה — (א) לא ראה ערך/חושב שיקר, או (ב) חושב שהתחום עצמו (שיווק) לא מתאים לו. הבן מה מאחורי זה לפני שאתה מגיב. אם ערך/מחיר: פרק את "לא שווה" — יש מוסדות שעולים הרבה יותר ואנשים בוחרים בהם בזכות הערך/הקשרים/הדלתות; הערך הוא ששווה, לא המחיר. אל תנקוב במחיר/סכום. אם התחום: הבן למה הוא חושב שלא מתאים לו, והראה למה כן — רק אם זה באמת נכון; אחרת שחרר בכנות. הובל את מי שמתאים לזום.$w$),
        (91, $w$חימום חם בלי שמץ אשמה — אל תשפוט, הנח שקרה משהו, קל-קל לקבוע מחדש. גלה את הסיבה האמיתית (רגליים קרות מול טיימינג) ונטרל אותה לפני הקביעה החוזרת — אחרת יבריז שוב. רענן את המטרה/הכאב שלו כך שהזום ישווה הופעה, ובנה מחויבות חזקה יותר.$w$)
     ) as v(status_sub, txt)
where r.agent_id = a.id
  and a.name = 'affiliate_marketing'
